"use strict";function numberFormat(r,e,t,i){t=void 0!==t?t:".",i=void 0!==i?i:",";var n=r.toFixed(e).split(".");return n[0]=n[0].replace(/\B(?=(\d{3})+(?!\d))/g,i),n.join(t)}function initNumberTicker(){gsap.utils.toArray(".numbers-module .number-number .val").forEach(r=>{const e=r.textContent,t={var:0},i=e%1>0?1:0;gsap.to(t,{var:e,duration:2,ease:"power1.in",scrollTrigger:{trigger:r},onUpdate(e){r.textContent=numberFormat(t.var,i,",",".")}})})}gsap.registerPlugin(ScrollTrigger),initNumberTicker(),AOS.init();